/// @title AGIToken  (placeholder "AGI" — confirm name at launch)
/// @notice Fixed-cap ERC-20 minted only by the mint contract up to MAX_SUPPLY. Before trading is
///         enabled only the mint contract can move tokens (escrow/launch phase non-transferable).
///         After launch any wallet / plain contract can receive; rogue pools are refused. The
///         liquidity pair is the OFFICIAL Uniswap V2 pair.
///
///         Trade tax (immutable constants, no setter):
///           BUY  1.0% = 0.5% treasury (accrues here, swept to WETH) + 0.5% BURNED on the spot.
///           SELL 1.0% -> accrues here, swept to WETH for the treasury.
///           wallet<->wallet: 0% (untaxed).
///         No swap ever runs inside a user transfer; the treasury sweep is a separate,
///         permissionless, per-block, pool-capped call. The mint contract burns pool inventory
///         (floor line) via burnFromPair, and un-mints refunded pre-open stakes via burnFromHolder.
contract AGIToken is ERC20 {
    uint256 public constant MAX_SUPPLY = 4_440_000_000 ether; // 4,440,000,000 (4.44B hard cap)

    uint256 public constant BUY_TREASURY_BPS = 50;    // 0.5% buy -> treasury
    uint256 public constant BUY_BURN_BPS = 50;        // 0.5% buy -> burned
    uint256 public constant SELL_TAX_BPS = 100;       // 1.0% sell -> treasury

    uint256 private constant SWAP_FEE_BPS = 30;   // Uniswap V2 fee (0.30%)
    uint256 private constant MAX_SWEEP_BPS = 50;  // <=0.5% of pool token reserve per sweep
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address public constant V4_POOLMANAGER = 0x000000000004444c5dc75cB358380D2e3dE08A90; // Uniswap V4 singleton — never allow pooling there (tax bypass)

    address public immutable quote; // WETH
    address public immutable pair;  // official Uniswap V2 pair (this, WETH)

    address public deployer;
    address public minter;
    address public treasury;
    bool public tradingEnabled;
    bool public blocksDisabled;
    bool private _locked;
    uint256 public lastSweepBlock;
    mapping(address => bool) public blockedPool;

    event TradingEnabled(uint256 at);
    event PoolBlocked(address indexed pool, bool blocked);
    event BlocksDisabled();
    event TaxSwept(uint256 tokensIn, uint256 ethOut);
    event Burned(uint256 amount);

    error NotDeployer();
    error NotMinter();
    error AlreadyInitialized();
    error ZeroAddress();
    error TransfersClosed();
    error PoolRejected();
    error SupplyCap();
    error Reentrancy();
    error SweptThisBlock();
    error NothingToSweep();
    error NotTradingYet();
    error PayoutFailed();

    constructor(address weth_, address factory_) ERC20("AgentID", "AGI") {
        if (weth_ == address(0) || factory_ == address(0)) revert ZeroAddress();
        quote = weth_;
        pair = IDexFactory(factory_).createPair(address(this), weth_);
        deployer = msg.sender;
    }

    /// @notice One-time wiring of the mint contract; clears the deployer afterwards.
    function initialize(address minter_) external {
        if (msg.sender != deployer) revert NotDeployer();
        if (minter != address(0)) revert AlreadyInitialized();
        if (minter_ == address(0)) revert ZeroAddress();
        minter = minter_;
        deployer = address(0);
        address t = IMintTreasury(minter_).treasury();
        if (t == address(0)) revert ZeroAddress();
        treasury = t;
    }

    modifier onlyMinter() {
        if (msg.sender != minter) revert NotMinter();
        _;
    }

    modifier nonReentrant() {
        if (_locked) revert Reentrancy();
        _locked = true;
        _;
        _locked = false;
    }

    function mint(address to, uint256 amount) external onlyMinter {
        if (totalSupply() + amount > MAX_SUPPLY) revert SupplyCap();
        _mint(to, amount);
    }

    function enableTrading() external onlyMinter {
        if (tradingEnabled) return;
        tradingEnabled = true;
        emit TradingEnabled(block.timestamp);
    }

    /// @notice Moves pool inventory to the dead address for the floor-line mechanism. The mint
    ///         contract syncs the pair immediately afterwards. (pair & DEAD: no tax, no guard)
    function burnFromPair(uint256 amount) external onlyMinter {
        super._update(pair, DEAD, amount);
    }

    /// @notice Burns tokens from `holder` (supply down). Only the mint contract, only to un-mint a
    ///         refunded pre-open stake; bypasses the pre-trading transfer lock.
    function burnFromHolder(address holder, uint256 amount) external onlyMinter {
        _burn(holder, amount);
    }

    function setPoolBlocked(address pool, bool blocked) external onlyMinter {
        blockedPool[pool] = blocked;
        emit PoolBlocked(pool, blocked);
    }

    function disableBlocks() external onlyMinter {
        blocksDisabled = true;
        emit BlocksDisabled();
    }

    // ------------------------------------------------------------- pool guard
    /// @notice Pool guard. Only the official pair ever receives taxed liquidity. We no longer probe
    ///         every contract recipient (removed: it added gas and read as a suspicious transfer
    ///         restriction to bot/honeypot simulators). The Uniswap V4 singleton is blocked by
    ///         constant, and the treasury can block a specific rogue pool manually if one ever gets
    ///         funded (disableable). All other recipients pass; wallet<->wallet stays untaxed.
    function rejects(address to) public view returns (bool) {
        if (to == pair) return false;
        if (to == V4_POOLMANAGER) return true; // block pooling on Uniswap V4
        if (blockedPool[to] && !blocksDisabled) return true; // treasury can block a rogue pool manually
        return false;
    }

    // ------------------------------------------------------------- transfers + tax
    function _update(address from, address to, uint256 value) internal override {
        if (from == address(0) || to == address(0)) {
            super._update(from, to, value); // mint / burn
            return;
        }
        address m = minter;
        if (!tradingEnabled) {
            if (from != m) revert TransfersClosed();
            super._update(from, to, value);
            return;
        }
        if (rejects(to)) revert PoolRejected();
        // mint contract and this token move untaxed (seeding, floor, sweeping)
        if (from == m || to == m || from == address(this) || to == address(this)) {
            super._update(from, to, value);
            return;
        }
        if (from == pair) {
            // BUY: 1.0% -> treasury (accrue here), 1.5% -> burned.
            uint256 toTreasury = (value * BUY_TREASURY_BPS) / 10_000;
            uint256 toBurn = (value * BUY_BURN_BPS) / 10_000;
            super._update(from, address(this), toTreasury);
            super._update(from, address(0), toBurn); // burn: supply down
            super._update(from, to, value - toTreasury - toBurn);
            emit Burned(toBurn);
        } else if (to == pair) {
            // SELL: 2.5% -> this contract (treasury path).
            uint256 tax = (value * SELL_TAX_BPS) / 10_000;
            super._update(from, address(this), tax);
            super._update(from, to, value - tax);
        } else {
            super._update(from, to, value); // wallet <-> wallet: untaxed
        }
    }

    // ------------------------------------------------------------- treasury sweep (token -> ETH)
    /// @notice Swap accrued tax tokens held here into WETH and send it to the treasury.
    ///         Permissionless, once per block, capped at 0.5% of the pool token reserve per call
    ///         (can never dump the pool). No swap runs inside a user transfer.
    function swapTaxToTreasury() external nonReentrant {
        if (!tradingEnabled) revert NotTradingYet();
        if (lastSweepBlock == block.number) revert SweptThisBlock();

        (uint112 r0, uint112 r1,) = IDexPair(pair).getReserves();
        bool tokenIs0 = IDexPair(pair).token0() == address(this);
        uint256 rTok = tokenIs0 ? uint256(r0) : uint256(r1);
        uint256 rQuote = tokenIs0 ? uint256(r1) : uint256(r0);
        if (rTok == 0 || rQuote == 0) revert NotTradingYet();

        uint256 bal = balanceOf(address(this));
        uint256 cap = (rTok * MAX_SWEEP_BPS) / 10_000;
        uint256 amount = bal > cap ? cap : bal;
        if (amount == 0) revert NothingToSweep();
        lastSweepBlock = block.number;

        super._update(address(this), pair, amount); // untaxed (from == this)
        uint256 out = DexMath.amountOut(amount, rTok, rQuote, SWAP_FEE_BPS);
        (uint256 out0, uint256 out1) = tokenIs0 ? (uint256(0), out) : (out, uint256(0));
        // Send the swapped WETH straight to the treasury. Uniswap V2 rejects `to` being a pair
        // token, so we cannot route it back through this contract; the treasury receives WETH
        // (it can unwrap to ETH at any time).
        IDexPair(pair).swap(out0, out1, treasury, "");
        emit TaxSwept(amount, out);
    }

    receive() external payable {} // ETH from WETH.withdraw during a sweep
}

